'use strict';class GeofenceManager{constructor(opts={}){this._opts=Object.assign({mapContainer:'geofence-map',apiBase:'/crm/api/geofence.php',csrfToken:'',planId:null,mode:'view',center:[49.2827,-123.1207],zoom:17,tileUrl:'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',tileAttrib:'Tiles &copy; Esri &mdash; Source: Esri, i-cubed, USDA, USGS, AEX, GeoEye, Getmapping, Aerogrid, IGN, IGP, UPR-EGP, and the GIS User Community',labelsUrl:'https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}',strokeColor:'#2D8659',fillColor:'#2D8659',fillOpacity:0.12,onSave:null,onDelete:null,onLoad:null,onDraw:null,onInZoneChange:null,},opts);this._map=null;this._polygonLayer=null;this._drawMarkers=[];this._drawLatLngs=[];this._drawLine=null;this._ring=[];this._bbox=null;this._isDrawing=!1;this._isSaving=!1;this._geofenceId=null;this._lastInZone=null}
init(){this._initMap();if(this._opts.planId){this._loadPolygon()}
return this}
destroy(){if(this._map){this._map.remove();this._map=null}}
_initMap(){const container=typeof this._opts.mapContainer==='string'?document.getElementById(this._opts.mapContainer):this._opts.mapContainer;if(!container){console.warn('[GeofenceManager] Map container not found:',this._opts.mapContainer);return}
if(typeof L==='undefined'){console.error('[GeofenceManager] Leaflet.js is not loaded.');return}
this._map=L.map(container,{center:this._opts.center,zoom:this._opts.zoom,zoomControl:!0,});L.tileLayer(this._opts.tileUrl,{attribution:this._opts.tileAttrib,maxNativeZoom:19,maxZoom:21,}).addTo(this._map);if(this._opts.labelsUrl){L.tileLayer(this._opts.labelsUrl,{attribution:'',maxNativeZoom:19,maxZoom:21,opacity:0.85,}).addTo(this._map)}
if(this._opts.mode==='edit'){this._map.on('click',(e)=>this._onMapClick(e));this._map.on('dblclick',(e)=>{if(this._isDrawing&&this._drawLatLngs.length>=3){this._finishDraw()}})}}
_loadPolygon(){const url=`${this._opts.apiBase}?action=get_polygon&plan_id=${this._opts.planId}`;fetch(url,{credentials:'same-origin'}).then(r=>r.json()).then(data=>{const hasPolygon=!!(data.polygon&&data.polygon.ring);if(hasPolygon){this._geofenceId=data.polygon.id;this._ring=data.polygon.ring;this._bbox=data.polygon.bbox||null;this._renderPolygon(data.polygon.ring);this._fitBounds()}
if(typeof this._opts.onLoad==='function'){this._opts.onLoad(hasPolygon)}}).catch(err=>console.warn('[GeofenceManager] Load polygon failed:',err))}
_renderPolygon(ring){this._clearPolygon();if(!ring||ring.length<3||!this._map)return;const latLngs=ring.map(pt=>L.latLng(pt[0],pt[1]));this._polygonLayer=L.polygon(latLngs,{color:this._opts.strokeColor,fillColor:this._opts.fillColor,fillOpacity:this._opts.fillOpacity,weight:2.5,dashArray:this._opts.mode==='edit'?'6 4':null,}).addTo(this._map)}
_clearPolygon(){if(this._polygonLayer){this._map.removeLayer(this._polygonLayer);this._polygonLayer=null}}
_fitBounds(){if(this._ring.length&&this._map){const latLngs=this._ring.map(pt=>L.latLng(pt[0],pt[1]));try{this._map.fitBounds(L.latLngBounds(latLngs).pad(0.1))}catch{}}}
startDraw(){if(this._opts.mode!=='edit')return;this._isDrawing=!0;this._drawLatLngs=[];this._clearDrawMarkers();this._clearPolygon();if(this._map){this._map.doubleClickZoom.disable();this._map.getContainer().style.cursor='crosshair';this._showToast('Click to add vertices. Double-click or press Finish to close the shape.','info')}}
cancelDraw(){this._isDrawing=!1;this._clearDrawMarkers();if(this._drawLine){this._map.removeLayer(this._drawLine);this._drawLine=null}
if(this._map){this._map.doubleClickZoom.enable();this._map.getContainer().style.cursor=''}
if(this._ring.length)this._renderPolygon(this._ring);}
finishDraw(){if(this._isDrawing)this._finishDraw();}
_onMapClick(e){if(!this._isDrawing)return;const{lat,lng}=e.latlng;this._drawLatLngs.push([lat,lng]);const marker=L.circleMarker([lat,lng],{radius:5,color:'#0D3B2E',fillColor:'#7FD858',fillOpacity:1,weight:2,}).addTo(this._map);this._drawMarkers.push(marker);if(this._drawLine)this._map.removeLayer(this._drawLine);if(this._drawLatLngs.length>1){this._drawLine=L.polyline(this._drawLatLngs,{color:this._opts.strokeColor,weight:2,dashArray:'5 5',}).addTo(this._map)}}
_finishDraw(){if(this._drawLatLngs.length<3){this._showToast('Need at least 3 vertices to form a polygon.','warning');return}
const ring=[...this._drawLatLngs];this._isDrawing=!1;this._clearDrawMarkers();if(this._drawLine){this._map.removeLayer(this._drawLine);this._drawLine=null}
if(this._map){this._map.doubleClickZoom.enable();this._map.getContainer().style.cursor=''}
this._ring=ring;this._bbox=this._computeBbox(ring);this._renderPolygon(ring);this._fitBounds();this._showToast(`Polygon drawn (${ring.length} vertices). Click Save to confirm.`,'success');if(typeof this._opts.onDraw==='function'){this._opts.onDraw(ring)}}
_clearDrawMarkers(){this._drawMarkers.forEach(m=>{if(this._map)this._map.removeLayer(m);});this._drawMarkers=[];this._drawLatLngs=[]}
save(label='',notes=''){if(this._isSaving)return Promise.reject(new Error('Already saving'));if(this._ring.length<3)return Promise.reject(new Error('No polygon to save'));if(!this._opts.planId)return Promise.reject(new Error('planId not set'));this._isSaving=!0;const body=JSON.stringify({action:'save_polygon',csrf_token:this._opts.csrfToken,plan_id:this._opts.planId,ring:this._ring,label:label||null,notes:notes||null,});return fetch(this._opts.apiBase,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body,}).then(r=>r.json()).then(data=>{this._isSaving=!1;if(!data.success)throw new Error(data.error||'Save failed');this._geofenceId=data.geofence_id;this._showToast('Polygon saved.','success');if(typeof this._opts.onSave==='function'){this._opts.onSave(data.geofence_id)}
return data}).catch(err=>{this._isSaving=!1;this._showToast('Save failed: '+err.message,'error');throw err})}
deletePolygon(){if(!this._opts.planId)return Promise.reject(new Error('planId not set'));const body=JSON.stringify({action:'delete_polygon',csrf_token:this._opts.csrfToken,plan_id:this._opts.planId,});return fetch(this._opts.apiBase,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body,}).then(r=>r.json()).then(data=>{if(!data.success)throw new Error(data.error||'Delete failed');this._geofenceId=null;this._ring=[];this._bbox=null;this._clearPolygon();this._showToast('Polygon deleted.','success');if(typeof this._opts.onDelete==='function')this._opts.onDelete();return data}).catch(err=>{this._showToast('Delete failed: '+err.message,'error');throw err})}
setPolygon(ring,geofenceId=null){this._ring=ring||[];this._bbox=ring?this._computeBbox(ring):null;this._geofenceId=geofenceId;if(this._map){this._renderPolygon(ring);this._fitBounds()}}
checkPoint(lat,lng){if(!this._ring.length||this._ring.length<3){return{inZone:!1,noPolygon:!0}}
if(this._bbox){if(lat<this._bbox.lat_min||lat>this._bbox.lat_max)return{inZone:!1};if(lng<this._bbox.lng_min||lng>this._bbox.lng_max)return{inZone:!1}}
const inZone=this._pointInPolygon(lat,lng,this._ring);if(inZone!==this._lastInZone){this._lastInZone=inZone;if(typeof this._opts.onInZoneChange==='function'){this._opts.onInZoneChange(inZone)}}
return{inZone}}
_pointInPolygon(lat,lng,polygon){let inside=!1;const n=polygon.length;let j=n-1;for(let i=0;i<n;i++){const xi=polygon[i][0],yi=polygon[i][1];const xj=polygon[j][0],yj=polygon[j][1];const intersect=((yi>lng)!==(yj>lng))&&(lat<(xj-xi)*(lng-yi)/(yj-yi)+xi);if(intersect)inside=!inside;j=i}
return inside}
_computeBbox(ring){if(!ring||!ring.length)return null;const lats=ring.map(p=>p[0]);const lngs=ring.map(p=>p[1]);return{lat_min:Math.min(...lats),lat_max:Math.max(...lats),lng_min:Math.min(...lngs),lng_max:Math.max(...lngs),}}
updateCrewPosition(lat,lng,inZone){if(!this._map)return;const color=inZone?'#2D8659':'#dc3545';if(!this._crewMarker){this._crewMarker=L.circleMarker([lat,lng],{radius:9,color,fillColor:color,fillOpacity:0.8,weight:2,}).addTo(this._map)}else{this._crewMarker.setLatLng([lat,lng]);this._crewMarker.setStyle({color,fillColor:color})}}
_showToast(msg,type='info'){if(window.showToast){window.showToast(msg,type)}else if(window.mowToast){window.mowToast(msg,type)}else{console.log(`[GeofenceManager][${type}] ${msg}`)}}
get ring(){return this._ring}
get geofenceId(){return this._geofenceId}
get hasPolygon(){return this._ring.length>=3}
get isDrawing(){return this._isDrawing}}
if(typeof module!=='undefined'&&module.exports){module.exports={GeofenceManager}}else{window.GeofenceManager=GeofenceManager}